const dictionaries: Record<ViewLocale, Record<TranslationKey, string>> = { 'en-US': enUS, 'zh-CN': zhCN }

export type Translator = (key: TranslationKey, values?: Record<string, string | number>) => string

export function translator(locale: ViewLocale): Translator {
  const dictionary = dictionaries[locale]
  return (key, values = {}) => Object.entries(values).reduce(
    (value, [name, replacement]) => value.replaceAll(`{${name}}`, String(replacement)),
    dictionary[key],
  )
}
